import{_ as i,c as a,o as e,a0 as o}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Schede di esercizi di gioco mentale","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/it/exercise-worksheets.md","filePath":"public/downloads/it/exercise-worksheets.md"}');const r=i({name:"public/downloads/it/exercise-worksheets.md"},[["render",function(i,t,r,_,l,n){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="schede-di-esercizi-di-gioco-mentale" tabindex="-1">Schede di esercizi di gioco mentale <a class="header-anchor" href="#schede-di-esercizi-di-gioco-mentale" aria-label="Permalink to &quot;Schede di esercizi di gioco mentale&quot;">​</a></h1><p><strong>Accademia di bocce - Esercizi pratici</strong></p><hr><h2 id="esercizio-1-riflessione-dello-stato-di-flusso" tabindex="-1">Esercizio 1: Riflessione dello stato di flusso <a class="header-anchor" href="#esercizio-1-riflessione-dello-stato-di-flusso" aria-label="Permalink to &quot;Esercizio 1: Riflessione dello stato di flusso&quot;">​</a></h2><h3 id="quando-hai-sperimentato-il-flow" tabindex="-1">Quando hai sperimentato il Flow? <a class="header-anchor" href="#quando-hai-sperimentato-il-flow" aria-label="Permalink to &quot;Quando hai sperimentato il Flow?&quot;">​</a></h3><p>Pensa a un&#39;occasione in cui hai giocato alla tua migliore partita a bocce:</p><p><strong>Descrivi la situazione:</strong></p><ul><li>Di quale torneo/partita si trattava?</li><li>Quali erano le condizioni?</li><li>Con chi stavi giocando?</li></ul><hr><hr><p><strong>Come ti sei sentito?</strong></p><ul><li>Qual era il tuo stato mentale?</li><li>Come ti è sembrato il tempo?</li><li>A cosa stavi pensando (o non pensando)?</li></ul><hr><hr><p><strong>Cosa ti ha aiutato ad arrivare fin qui?</strong></p><ul><li>Cosa hai fatto prima della partita?</li><li>Cosa c&#39;era di diverso quel giorno?</li><li>È possibile ricreare qualcuna di queste condizioni?</li></ul><hr><hr><hr><h2 id="esercizio-2-inventario-del-critico-interiore" tabindex="-1">Esercizio 2: Inventario del critico interiore <a class="header-anchor" href="#esercizio-2-inventario-del-critico-interiore" aria-label="Permalink to &quot;Esercizio 2: Inventario del critico interiore&quot;">​</a></h2><h3 id="identifica-il-tuo-critico-interiore" tabindex="-1">Identifica il tuo critico interiore <a class="header-anchor" href="#identifica-il-tuo-critico-interiore" aria-label="Permalink to &quot;Identifica il tuo critico interiore&quot;">​</a></h3><p><strong>Cosa dice il tuo Critico Interiore?</strong></p><p>Elenca 3-5 pensieri critici comuni che hai durante una competizione:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Quando appare?</strong></p><ul><li>Dopo gli errori? □</li><li>Prima di scatti importanti? □</li><li>Quando giochi contro avversari forti? □</li><li>Quando i compagni di squadra guardano? □</li><li>Altro: _______________________________________________</li></ul><hr><h2 id="esercizio-3-riformulazione-della-pratica" tabindex="-1">Esercizio 3: Riformulazione della pratica <a class="header-anchor" href="#esercizio-3-riformulazione-della-pratica" aria-label="Permalink to &quot;Esercizio 3: Riformulazione della pratica&quot;">​</a></h2><h3 id="trasformare-il-critico-in-allenatore" tabindex="-1">Trasformare il critico in allenatore <a class="header-anchor" href="#trasformare-il-critico-in-allenatore" aria-label="Permalink to &quot;Trasformare il critico in allenatore&quot;">​</a></h3><p><strong>Per ogni pensiero del Critico Interiore, scrivi una riformulazione del Coach Interiore:</strong></p><table tabindex="0"><thead><tr><th>Critico Interiore</th><th>Coach Interiore</th></tr></thead><tbody><tr><td>Esempio: &quot;Quando sono sotto pressione sbaglio sempre&quot;</td><td>&quot;Ho già avuto successo sotto pressione, posso farlo di nuovo&quot;</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Esercitati a dirle ad alta voce</strong></p><hr><h2 id="esercizio-4-progettazione-della-routine-pre-tiro" tabindex="-1">Esercizio 4: Progettazione della routine pre-tiro <a class="header-anchor" href="#esercizio-4-progettazione-della-routine-pre-tiro" aria-label="Permalink to &quot;Esercizio 4: Progettazione della routine pre-tiro&quot;">​</a></h2><h3 id="crea-la-tua-routine-personale" tabindex="-1">Crea la tua routine personale <a class="header-anchor" href="#crea-la-tua-routine-personale" aria-label="Permalink to &quot;Crea la tua routine personale&quot;">​</a></h3><p>Progetta una routine pre-tiro in 4 fasi adatta a te:</p><p><strong>Passaggio 1: Visualizza</strong></p><ul><li>Cosa visualizzerai esattamente?</li><li>Quanto tempo (2-3 secondi)?</li></ul><hr><p><strong>Passaggio 2: Respira</strong></p><ul><li>Un respiro profondo o tre?</li><li>C&#39;è qualche schema specifico?</li></ul><hr><p><strong>Passaggio 3: Ancoraggio</strong></p><ul><li>Quale ancoraggio fisico utilizzerai?</li><li>Tocca la boccia? Posizione specifica?</li></ul><hr><p><strong>Passaggio 4: Esecuzione</strong></p><ul><li>Qual è il tuo segnale mentale?</li><li>&quot;Fiducia&quot; / &quot;Flusso&quot; / &quot;Vai&quot;?</li></ul><hr><p><strong>Esegui questa routine 10 volte oggi</strong></p><hr><h2 id="esercizio-5-fattori-scatenanti-della-pressione" tabindex="-1">Esercizio 5: Fattori scatenanti della pressione <a class="header-anchor" href="#esercizio-5-fattori-scatenanti-della-pressione" aria-label="Permalink to &quot;Esercizio 5: Fattori scatenanti della pressione&quot;">​</a></h2><h3 id="identifica-i-tuoi-punti-di-pressione" tabindex="-1">Identifica i tuoi punti di pressione <a class="header-anchor" href="#identifica-i-tuoi-punti-di-pressione" aria-label="Permalink to &quot;Identifica i tuoi punti di pressione&quot;">​</a></h3><p><strong>Quali situazioni ti mettono sotto pressione?</strong></p><p>Valuta ciascuna azione da 1 (nessuna pressione) a 10 (pressione estrema):</p><ul><li>Giocare contro avversari forti: ___/10</li><li>Partite importanti del torneo: ___/10</li><li>Punteggio pari, tiro finale: ___/10</li><li>Dopo aver commesso un errore: ___/10</li><li>Quando i compagni di squadra guardano: ___/10</li><li>Quando gioco male: ___/10</li><li>Altro: _________________________ ___/10</li></ul><p><strong>Per il trigger con il punteggio più alto:</strong></p><p>Quali sensazioni fisiche noti?</p><hr><p>Quali pensieri appaiono?</p><hr><p>Quale tecnica utilizzerai?</p><ul><li>[ ] 3-Reset del respiro</li><li>[ ] Routine pre-tiro</li><li>[ ] Riformulazione</li><li>[ ] Altro: _____________________</li></ul><hr><h2 id="esercizio-6-pratica-di-cambio-di-modalita" tabindex="-1">Esercizio 6: Pratica di cambio di modalità <a class="header-anchor" href="#esercizio-6-pratica-di-cambio-di-modalita" aria-label="Permalink to &quot;Esercizio 6: Pratica di cambio di modalità&quot;">​</a></h2><h3 id="pianificazione-vs-esecuzione" tabindex="-1">Pianificazione vs Esecuzione <a class="header-anchor" href="#pianificazione-vs-esecuzione" aria-label="Permalink to &quot;Pianificazione vs Esecuzione&quot;">​</a></h3><p><strong>Esercitati con lo scambio:</strong></p><p><strong>Fase di pianificazione (prima dello scatto):</strong></p><ul><li>Cosa devo analizzare?</li><li>Qual è la mia strategia?</li><li>Quale scatto sceglierò?</li></ul><p><strong>Fase di esecuzione (durante lo scatto):</strong></p><ul><li>Libera la mente</li><li>Fidati del tuo corpo</li><li>Lascia che accada</li></ul><p><strong>Esercizio pratico:</strong></p><p>Fai 5 tiri di prova. Per ognuno:</p><ol><li>Trascorri 10 secondi in modalità pianificazione (analizza, decidi)</li><li>Fai 3 respiri per cambiare modalità</li><li>Eseguire in modalità flusso (senza pensare)</li></ol><p><strong>Riflessione:</strong></p><ul><li>Riesci a sentire la differenza tra le modalità?</li><li>L&#39;interruttore era libero?</li><li>Quale modalità è più difficile per te?</li></ul><hr><hr><hr><h2 id="esercizio-7-piano-di-pratica-settimanale" tabindex="-1">Esercizio 7: Piano di pratica settimanale <a class="header-anchor" href="#esercizio-7-piano-di-pratica-settimanale" aria-label="Permalink to &quot;Esercizio 7: Piano di pratica settimanale&quot;">​</a></h2><h3 id="focus-di-questa-settimana" tabindex="-1">Focus di questa settimana <a class="header-anchor" href="#focus-di-questa-settimana" aria-label="Permalink to &quot;Focus di questa settimana&quot;">​</a></h3><p><strong>Scegli UNA tecnica da praticare:</strong></p><ul><li>[ ] 3-Reset del respiro dopo ogni errore</li><li>[ ] Routine pre-tiro su ogni lancio</li><li>[ ] Riformula un pensiero del Critico Interiore per sessione</li><li>[ ] Commutazione della modalità di pratica</li></ul><p><strong>Pratica quotidiana:</strong></p><table tabindex="0"><thead><tr><th>Giorno</th><th>Attività pratica</th><th>Durata</th><th>Note</th></tr></thead><tbody><tr><td>Lun</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Mar</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Mer</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Gio</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Ven</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sab</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sole</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="esercizio-8-monitoraggio-dei-progressi" tabindex="-1">Esercizio 8: Monitoraggio dei progressi <a class="header-anchor" href="#esercizio-8-monitoraggio-dei-progressi" aria-label="Permalink to &quot;Esercizio 8: Monitoraggio dei progressi&quot;">​</a></h2><h3 id="riflessione-di-fine-settimana" tabindex="-1">Riflessione di fine settimana <a class="header-anchor" href="#riflessione-di-fine-settimana" aria-label="Permalink to &quot;Riflessione di fine settimana&quot;">​</a></h3><p><strong>Cosa hai fatto questa settimana?</strong></p><hr><p><strong>Cosa hai notato?</strong></p><hr><hr><p><strong>Cosa ha funzionato bene?</strong></p><hr><hr><p><strong>Qual è stata la sfida?</strong></p><hr><hr><p><strong>Cosa continuerai la prossima settimana?</strong></p><hr><hr><p><strong>Cosa modificherai?</strong></p><hr><hr><hr><h2 id="prossimi-passi" tabindex="-1">Prossimi passi <a class="header-anchor" href="#prossimi-passi" aria-label="Permalink to &quot;Prossimi passi&quot;">​</a></h2><h3 id="continua-il-tuo-sviluppo" tabindex="-1">Continua il tuo sviluppo <a class="header-anchor" href="#continua-il-tuo-sviluppo" aria-label="Permalink to &quot;Continua il tuo sviluppo&quot;">​</a></h3><p><strong>Risorse su carreau.app:</strong></p><ul><li>Modello di obiettivo: struttura il tuo sviluppo a lungo termine</li><li>Modello di diario - Tieni traccia dei progressi giornalieri</li><li>The Zone - Immersione profonda negli stati di flusso</li><li>Forza mentale - Gestione avanzata della pressione</li></ul><p><strong>Continua a esercitarti:</strong></p><ul><li>Le capacità mentali necessitano di un allenamento costante</li><li>Inizia in piccolo, costruisci gradualmente</li><li>Tieni traccia dei tuoi progressi</li><li>Festeggia i miglioramenti</li></ul><hr><p><em>Accademia di bocce - Sviluppo dei giocatori d&#39;élite</em><em>carreau.app</em></p>',113)])])}]]);export{t as __pageData,r as default};
